/*
 * Hand-written part of the dummy libsystemd.
 *
 * These are the sd-daemon and sd-journal entry points that are safe to
 * answer with "systemd is not here" instead of failing. Everything else is
 * generated by tools/gen-stub.sh and returns -ENOSYS or NULL.
 *
 * No libc is used on purpose: this keeps the stub free of DT_NEEDED and of
 * any GLIBC_* version requirement, which matters for ppc64 and for building
 * with zig.
 */

#include <stdarg.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <sys/uio.h>

int sd_booted(void) {
	return 0; /* not booted with systemd */
}

int sd_listen_fds(int unset_environment) {
	(void) unset_environment;
	/* socket activation is deliberately not emulated */
	return 0;
}

int sd_listen_fds_with_names(int unset_environment, char ***names) {
	(void) unset_environment;
	if (names)
		*names = NULL;
	return 0;
}

int sd_is_socket(int fd, int family, int type, int listening) {
	(void) fd; (void) family; (void) type; (void) listening;
	return 0;
}

int sd_is_socket_inet(int fd, int family, int type, int listening, uint16_t port) {
	(void) fd; (void) family; (void) type; (void) listening; (void) port;
	return 0;
}

int sd_is_socket_unix(int fd, int type, int listening, const char *path, size_t length) {
	(void) fd; (void) type; (void) listening; (void) path; (void) length;
	return 0;
}

int sd_is_socket_sockaddr(int fd, int type, const struct sockaddr *addr,
			  unsigned addr_len, int listening) {
	(void) fd; (void) type; (void) addr; (void) addr_len; (void) listening;
	return 0;
}

int sd_is_fifo(int fd, const char *path) {
	(void) fd; (void) path;
	return 0;
}

int sd_is_special(int fd, const char *path) {
	(void) fd; (void) path;
	return 0;
}

int sd_is_mq(int fd, const char *path) {
	(void) fd; (void) path;
	return 0;
}

